/* Best records are independent of the bounded recent-history list. */
(function(root){'use strict';
function create(storage,history,valid,bucket){
 const key=history+'.best.v1';
 bucket=bucket||function(r){return JSON.stringify([r.game,r.ruleVersion||r.version,r.mode,r.difficulty,r.starter,r.outcome]);};
 function select(rows){const groups=new Map();for(const r of rows.filter(valid)){const k=bucket(r),a=groups.get(k)||[];a.push(r);groups.set(k,a);}const out=[];for(const a of groups.values()){const score=a.filter(r=>Number.isFinite(r.score)).sort((a,b)=>b.score-a.score)[0],moves=a.filter(r=>Number.isFinite(r.moves)).sort((a,b)=>a.moves-b.moves)[0],attempts=a.filter(r=>r.won&&Number.isFinite(r.attempts)).sort((a,b)=>a.attempts-b.attempts)[0];for(const r of[score,moves,attempts])if(r&&!out.some(x=>JSON.stringify(x)===JSON.stringify(r)))out.push(r);}return out;}
 function remember(incoming=[]){let saved=[],invalid=false;const parts=key+'.entry.';if(typeof storage.key==='function'){for(let i=0;i<storage.length;i++){const k=storage.key(i);if(k?.startsWith(parts)){try{const r=JSON.parse(storage.getItem(k));if(valid(r))saved.push(r);}catch{}}}}const raw=storage.getItem(key);if(raw){try{const x=JSON.parse(raw);if(!Array.isArray(x))throw Error();const accepted=x.filter(valid);saved.push(...accepted);invalid=accepted.length!==x.length;}catch{invalid=true;}}if(invalid&&!storage.getItem(key+'.backup'))storage.setItem(key+'.backup',raw);const rows=select([...saved,...incoming]);for(const r of rows){for(const [metric,higher]of [['score',true],['moves',false],['attempts',false]]){if(!Number.isFinite(r[metric])||(metric==='attempts'&&!r.won))continue;const part=parts+encodeURIComponent(bucket(r))+'.'+metric;let old;try{old=JSON.parse(storage.getItem(part));}catch{}if(old&&valid(old)&&Number.isFinite(old[metric])&&(higher?old[metric]>=r[metric]:old[metric]<=r[metric]))continue;storage.setItem(part,JSON.stringify(r));}}const next=JSON.stringify(rows);if(next!==raw)storage.setItem(key,next);return rows;}
 function read(){let incoming=[],error='';try{const raw=storage.getItem(history),rows=raw?JSON.parse(raw):[];if(!Array.isArray(rows))throw Error();incoming=rows;}catch{error='최근 기록을 읽지 못했습니다. 보존된 최고 기록을 표시합니다.';}try{return{rows:remember(incoming),error};}catch{let old=[];try{const x=JSON.parse(storage.getItem(key)||'[]');if(Array.isArray(x))old=x;}catch{}return{rows:select([...old,...incoming]),error:'최고 기록을 보존하지 못했습니다. 저장 공간을 확인해주세요.'};}}

 function clear(){storage.removeItem(key);if(typeof storage.key==='function'){const keys=[];for(let i=0;i<storage.length;i++){const k=storage.key(i);if(k?.startsWith(key+'.entry.'))keys.push(k);}for(const k of keys)storage.removeItem(k);}}
 return {key,remember,read,clear};
}
const api={create};if(typeof module!=='undefined')module.exports=api;root.RecordLedger=api;
})(typeof window==='undefined'?globalThis:window);
